import time
import logging

import requests
import attr
from six import raise_from

logger = logging.getLogger(__name__)


class AuthorizationFailed(Exception):
    pass


@attr.s(eq=True, frozen=True)
class TokenDetails(object):
    access_token = attr.ib(type=str)
    access_token_expires_in = attr.ib(type=int)
    refresh_token = attr.ib(type=str)
    refresh_token_expires_in = attr.ib(type=int)

    def __attrs_post_init__(self):
        object.__setattr__(self, "token_creation_time", time.time())

    @property
    def is_access_token_expired(self):
        # Due to network latency, operations' queuing on server side, etc., it might past some time
        # between checking of access token validity and user authorization based on it. During that
        # time access token may expire, leading to authorization failure. To avoid such case
        # refreshing of access token has to be triggered the right time before its expiration.
        return self.token_creation_time + self.access_token_expires_in < time.time() + 30

    @property
    def is_refresh_token_expired(self):
        return self.token_creation_time + self.refresh_token_expires_in < time.time() + 30


class Authorization(object):
    TOKEN_URL = 'auth/realms/master/protocol/openid-connect/token'

    @staticmethod
    def get_refresh_and_access_token_details_with_client_auth(client_id, client_secret, username, password,
                                                              user_mgmt_uri):
        logger.info('Acquiring refresh and access token using client credentials...')
        request_data = {
            "grant_type": 'password',
            "client_id": client_id,
            "client_secret": client_secret,
            "scope": "openid",
            "username": username,
            "password": password,
        }
        try:
            token_response = Authorization._get_authorization_response(user_mgmt_uri=user_mgmt_uri,
                                                                       request_data=request_data)
            return TokenDetails(
                access_token=token_response['access_token'],
                access_token_expires_in=int(token_response['expires_in']),
                refresh_token=token_response['refresh_token'],
                refresh_token_expires_in=int(token_response['refresh_expires_in'])
            )
        except Exception as e:
            raise_from(AuthorizationFailed, e)

    @staticmethod
    def get_refresh_and_access_token_details_with_refresh_token(refresh_token, client_id, client_secret, user_mgmt_uri):
        logger.info('Acquiring refresh and access token using valid refresh token...')
        request_data = {
            "grant_type": 'refresh_token',
            "client_id": client_id,
            "client_secret": client_secret,
            "scope": "openid",
            "refresh_token": refresh_token

        }
        try:
            token_response = Authorization._get_authorization_response(user_mgmt_uri=user_mgmt_uri,
                                                                       request_data=request_data)

            return TokenDetails(
                access_token=token_response['access_token'],
                access_token_expires_in=int(token_response['expires_in']),
                refresh_token=token_response['refresh_token'],
                refresh_token_expires_in=int(token_response['refresh_expires_in'])
            )
        except Exception as e:
            raise_from(AuthorizationFailed, e)

    @staticmethod
    def _get_authorization_response(user_mgmt_uri, request_data):
        client_token_endpoint = (
            "{um_uri}/auth/realms/NEO/protocol/openid-connect/token"
        ).format(um_uri=user_mgmt_uri)
        headers = {"Content-Type": "application/x-www-form-urlencoded"}
        data = request_data

        response = requests.post(
            client_token_endpoint, headers=headers, data=data, verify=False
        )

        response.raise_for_status()

        return response.json()


class TokenManager(object):

    def __init__(self, client_id, client_secret, username, password, user_mgmt_uri):
        self.client_id = client_id
        self.client_secret = client_secret
        self.username = username
        self.password = password
        self.user_mgmt_uri = user_mgmt_uri
        self.token_object = self.get_access_token()

    @property
    def access_token(self):
        return self.token_object.access_token

    def get_access_token(self):
        return Authorization.get_refresh_and_access_token_details_with_client_auth(
            self.client_id, self.client_secret, self.username, self.password, self.user_mgmt_uri)

    def get_refresh_access_token(self):
        return Authorization.get_refresh_and_access_token_details_with_refresh_token(
            self.token_object.refresh_token, self.client_id, self.client_secret, self.user_mgmt_uri)

    def assert_token_is_valid(self):
        if self.token_object.is_access_token_expired and not self.token_object.is_refresh_token_expired:
            self.token_object = self.get_refresh_access_token()
        elif self.token_object.is_refresh_token_expired:
            self.token_object = self.get_access_token()


class TokenProvider(object):

    @staticmethod
    def provide_access_token(f):
        def wrapper(nom_instance, *args, **kwargs):
            nom_instance.token.assert_token_is_valid()
            nom_instance.configuration.access_token = nom_instance.token.access_token
            return f(nom_instance, *args, **kwargs)

        return wrapper
